$PayloadBase64 = @{
    "backend\cms\api.py" = ""
    "backend\discovery\providers\udemy_free.py" = ""
    "backend\discovery\registry.py" = ""
    "backend\discovery\scrapy_app\extractors.py" = ""
    "backend\discovery\scrapy_app\runner.py" = ""
    "backend\discovery\scrapy_app\spiders\udemy_free.py" = ""
    "backend\discovery\tasks.py" = ""
    "backend\discovery\udemy_catalog.py" = ""
    "backend\tests\test_admin_discovery.py" = ""
    "backend\tests\test_phase5_discovery_operations.py" = ""
    "backend\tests\test_scrapy_udemy_crawler.py" = ""
    "backend\tests\test_udemy_free_provider.py" = ""
    "frontend\src\app\admin\discovery\page.tsx" = ""
    "frontend\src\lib\admin-api.ts" = ""
}

$Python = Join-Path $Root ".venv\Scripts\python.exe"
$Backups = New-Object 'System.Collections.Generic.List[string]'
$WriteStarted = $false

function Get-ProjectPath {
    param([string]$RelativePath)
    return Join-Path $Root ($RelativePath -replace '/', [IO.Path]::DirectorySeparatorChar)
}

function Get-NormalizedText {
    param([string]$Path)
    $text = [System.IO.File]::ReadAllText($Path)
    return (($text -replace "`r`n", "`n") -replace "`r", "`n")
}

function Get-NormalizedSha256 {
    param([string]$Path)
    $bytes = [Text.Encoding]::UTF8.GetBytes((Get-NormalizedText $Path))
    $sha = [Security.Cryptography.SHA256]::Create()
    try { $hash = $sha.ComputeHash($bytes) } finally { $sha.Dispose() }
    return ([BitConverter]::ToString($hash)).Replace("-", "").ToLowerInvariant()
}

function Fail-Preflight {
    param([string]$Message)
    throw ("Preflight failed: " + $Message + " No source files were changed.")
}

function Assert-Hash {
    param([string]$RelativePath, [string]$Expected, [string]$Label)
    $path = Get-ProjectPath $RelativePath
    if (-not (Test-Path -LiteralPath $path)) {
        Fail-Preflight ("required " + $Label + " file is missing: " + $RelativePath)
    }
    $actual = Get-NormalizedSha256 $path
    if ($actual -ne $Expected) {
        Fail-Preflight ($Label + " hash mismatch in " + $RelativePath + ". Expected " + $Expected + ", found " + $actual + ".")
    }
}

function Invoke-ExternalGate {
    param([string]$Label, [scriptblock]$Action)
    Write-Host ""
    Write-Host ("==> " + $Label)
    & $Action
    if ($LASTEXITCODE -ne 0) {
        throw ("Gate failed: " + $Label + " (exit code " + $LASTEXITCODE + ")")
    }
}

function Prepare-Backup {
    param([string]$RelativePath)
    $path = Get-ProjectPath $RelativePath
    $backup = $path + $BackupSuffix
    if (Test-Path -LiteralPath $backup) {
        $backupHash = Get-NormalizedSha256 $backup
        if ($backupHash -ne $ExpectedBaselineHashes[$RelativePath]) {
            Fail-Preflight ("existing patch backup does not match the accepted post-v2 baseline: " + $RelativePath + $BackupSuffix)
        }
        Write-Host ("Verified retained patch backup: " + $RelativePath + $BackupSuffix)
    }
    else {
        Copy-Item -LiteralPath $path -Destination $backup
    }
    $Backups.Add($backup)
}

function Write-Payload {
    param([string]$RelativePath)
    $path = Get-ProjectPath $RelativePath
    $bytes = [Convert]::FromBase64String($PayloadBase64[$RelativePath])
    [IO.File]::WriteAllBytes($path, $bytes)
}

function Restore-Source {
    Write-Host "Restoring modified source files from patch backups..."
    foreach ($backup in $Backups) {
        $original = $backup.Substring(0, $backup.Length - $BackupSuffix.Length)
        Copy-Item -LiteralPath $backup -Destination $original -Force
    }
    Write-Host "Source restoration completed. Patch backups were retained for verification."
}

function Remove-PatchBackups {
    foreach ($backup in $Backups) {
        if (Test-Path -LiteralPath $backup) {
            Remove-Item -LiteralPath $backup -Force
        }
    }
}

try {
    Write-Host ("Preflight: validating " + $BaselineDescription + "...")

    foreach ($entry in $ExpectedBaselineHashes.GetEnumerator()) {
        Assert-Hash $entry.Key $entry.Value "accepted post-v2 baseline"
    }
    foreach ($entry in $ExpectedGuardHashes.GetEnumerator()) {
        Assert-Hash $entry.Key $entry.Value "non-regression guard"
    }

    if (-not (Test-Path -LiteralPath $Python)) {
        Fail-Preflight "project virtualenv Python is missing at .venv\Scripts\python.exe"
    }

    $AgentPath = Get-ProjectPath "frontend\AGENTS.md"
    [void][IO.File]::ReadAllText($AgentPath)
    Write-Host ("Frontend agent guide read: " + $AgentPath)

    $NextGuide = Get-ProjectPath "frontend\node_modules\next\dist\docs\01-app\01-getting-started\05-server-and-client-components.md"
    if (-not (Test-Path -LiteralPath $NextGuide)) {
        Fail-Preflight "the bundled Next.js server/client components guide is missing; restore frontend node_modules before applying frontend changes"
    }
    [void][IO.File]::ReadAllText($NextGuide)
    Write-Host ("Bundled Next.js guide read: " + $NextGuide)

    foreach ($relative in $ModifiedFiles) {
        $backup = (Get-ProjectPath $relative) + $BackupSuffix
        if (Test-Path -LiteralPath $backup) {
            $backupHash = Get-NormalizedSha256 $backup
            if ($backupHash -ne $ExpectedBaselineHashes[$relative]) {
                Fail-Preflight ("existing patch backup does not match the accepted post-v2 baseline: " + $relative + $BackupSuffix)
            }
            Write-Host ("Verified retained patch backup: " + $relative + $BackupSuffix)
        }
    }

    if (Test-Path -LiteralPath (Join-Path $Root ".git")) {
        Write-Host "Git working tree before patch:"
        $env:GIT_PAGER = "cat"
        $env:PAGER = "cat"
        & git -C $Root --no-pager status --short
        if ($LASTEXITCODE -ne 0) { Fail-Preflight "git status failed" }
    }

    Invoke-ExternalGate "Preflight project virtualenv Django import" {
        & $Python -c "import django; print('DJANGO_VERSION=' + django.get_version())"
    }
    Invoke-ExternalGate "Preflight Django system check" {
        & $Python (Join-Path $Root "backend\manage.py") check
    }
    Invoke-ExternalGate "Preflight migration application check" {
        & $Python (Join-Path $Root "backend\manage.py") migrate --check
    }
    Invoke-ExternalGate "Preflight migration drift check" {
        & $Python (Join-Path $Root "backend\manage.py") makemigrations --check --dry-run
    }

    Write-Host ""
    Write-Host "Preflight PASS. Creating patch-owned backups..."
    foreach ($relative in $ModifiedFiles) { Prepare-Backup $relative }
    $WriteStarted = $true

    foreach ($relative in $ModifiedFiles) { Write-Payload $relative }

    foreach ($entry in $ExpectedTargetHashes.GetEnumerator()) {
        $path = Get-ProjectPath $entry.Key
        $actual = Get-NormalizedSha256 $path
        if ($actual -ne $entry.Value) {
            throw ("Target hash mismatch after write in " + $entry.Key + ". Expected " + $entry.Value + ", found " + $actual)
        }
    }
    Write-Host "Exact UTF-8 payload verification: PASS"

    $catalog = Get-NormalizedText (Get-ProjectPath "backend\discovery\udemy_catalog.py")
    $spider = Get-NormalizedText (Get-ProjectPath "backend\discovery\scrapy_app\spiders\udemy_free.py")
    $registry = Get-NormalizedText (Get-ProjectPath "backend\discovery\registry.py")
    $runner = Get-NormalizedText (Get-ProjectPath "backend\discovery\scrapy_app\runner.py")
    $cmsApi = Get-NormalizedText (Get-ProjectPath "backend\cms\api.py")
    $scrapySettings = Get-NormalizedText (Get-ProjectPath "backend\discovery\scrapy_app\settings.py")
    $services = Get-NormalizedText (Get-ProjectPath "backend\discovery\services.py")
    $adminPage = Get-NormalizedText (Get-ProjectPath "frontend\src\app\admin\discovery\page.tsx")
    $adminApi = Get-NormalizedText (Get-ProjectPath "frontend\src\lib\admin-api.ts")

    if (-not $catalog.Contains('UDEMY_DEFAULT_SEARCH_URL = "https://www.udemy.com/courses/free/"')) {
        throw "Semantic guard failed: all-topic discovery no longer uses the public free catalog."
    }
    if (-not $catalog.Contains('return f"https://www.udemy.com/topic/{topic_slug}/free/"')) {
        throw "Semantic guard failed: selected topics are not routed to public /topic/<topic>/free/ pages."
    }
    if (-not $catalog.Contains('Certification Prep discovery is not enabled yet')) {
        throw "Semantic guard failed: certification facet is being silently accepted or dropped."
    }
    if (-not $catalog.Contains('courseLabel IDs are blocked URL facets')) {
        throw "Semantic guard failed: numeric Udemy topic facets are being guessed."
    }
    if (-not $spider.Contains('exclude_file=""')) {
        throw "Semantic guard failed: cross-run existing-course exclusion is missing from the spider."
    }
    if (-not $spider.Contains('extract_udemy_course_language')) {
        throw "Semantic guard failed: English verification from public course pages is missing."
    }
    if (-not $spider.Contains('query["p"] = str(page_number)')) {
        throw "Semantic guard failed: pagination no longer uses the allowed p parameter."
    }
    if (-not $runner.Contains('exclude-course-urls.json')) {
        throw "Semantic guard failed: existing course URLs are not transferred to the isolated crawler safely."
    }
    if (-not $registry.Contains('skip_existing: bool = False')) {
        throw "Semantic guard failed: manual new-only discovery switch is missing."
    }
    if (-not $registry.Contains('Course.objects.filter(provider=provider)')) {
        throw "Semantic guard failed: manual runs do not snapshot existing course URLs."
    }
    if (-not $cmsApi.Contains('skip_existing=True')) {
        throw "Semantic guard failed: custom-admin manual discovery is not new-only."
    }
    if (-not $cmsApi.Contains('build_udemy_discovery_source')) {
        throw "Semantic guard failed: custom-admin topic selection is not mapped to a robots-compatible source."
    }
    if (-not $adminPage.Contains('label="Topic"')) {
        throw "Semantic guard failed: the custom-admin discovery dialog has no Topic control."
    }
    if (-not $adminPage.Contains('Number of new courses to scrape')) {
        throw "Semantic guard failed: the manual run UI no longer communicates new-only behavior."
    }
    if (-not $adminApi.Contains('topic, certification_only: certificationOnly')) {
        throw "Semantic guard failed: frontend discovery filters are not sent to the admin API."
    }
    if ($scrapySettings -notmatch 'ROBOTSTXT_OBEY\s*=\s*True') {
        throw "Semantic guard failed: robots compliance was disabled."
    }

    $mutableStart = $services.IndexOf("mutable_fields = {")
    $mutableEnd = $services.IndexOf("changed_fields:", $mutableStart)
    if ($mutableStart -lt 0 -or $mutableEnd -le $mutableStart) {
        throw "Semantic guard failed: discovery upsert mutable fields could not be isolated."
    }
    $mutableBlock = $services.Substring($mutableStart, $mutableEnd - $mutableStart)
    if ($mutableBlock.Contains('"category"') -or $mutableBlock.Contains('"language"')) {
        throw "Semantic guard failed: discovery must not overwrite human category or language fields."
    }

    Write-Host "Topic/new-only/English/robots semantic guards: PASS"

    Invoke-ExternalGate "Python syntax verification" {
        $paths = @($BackendPythonFiles | ForEach-Object { Get-ProjectPath $_ })
        & $Python -c "import ast,pathlib,sys; [ast.parse(pathlib.Path(p).read_text(encoding='utf-8'), filename=p) for p in sys.argv[1:]]" @paths
    }
    Invoke-ExternalGate "Django system check" {
        & $Python (Join-Path $Root "backend\manage.py") check
    }
    Invoke-ExternalGate "Migration application check" {
        & $Python (Join-Path $Root "backend\manage.py") migrate --check
    }
    Invoke-ExternalGate "Migration drift check" {
        & $Python (Join-Path $Root "backend\manage.py") makemigrations --check --dry-run
    }

    $FocusedPytestBaseTemp = Join-Path $Root (".pytest-learnloot-udemy-topic-focus-" + [Guid]::NewGuid().ToString("N"))
    $FullPytestBaseTemp = Join-Path $Root (".pytest-learnloot-udemy-topic-full-" + [Guid]::NewGuid().ToString("N"))
    Push-Location (Join-Path $Root "backend")
    try {
        Invoke-ExternalGate "Focused topic/new-only/Udemy discovery tests" {
            & $Python -m pytest `
                ("--basetemp=" + $FocusedPytestBaseTemp) `
                tests\test_admin_discovery.py `
                tests\test_phase5_discovery_operations.py `
                tests\test_scrapy_udemy_crawler.py `
                tests\test_udemy_free_provider.py `
                tests\test_discovery_pipeline.py `
                tests\test_phase12_taxonomy_images.py
        }
        Invoke-ExternalGate "Full backend regression suite" {
            & $Python -m pytest ("--basetemp=" + $FullPytestBaseTemp)
        }
    }
    finally {
        Pop-Location
        foreach ($testTemp in @($FocusedPytestBaseTemp, $FullPytestBaseTemp)) {
            if (Test-Path -LiteralPath $testTemp) {
                Remove-Item -LiteralPath $testTemp -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
    }

    Push-Location (Join-Path $Root "frontend")
    try {
        Invoke-ExternalGate "Frontend lint" { & npm.cmd run lint }
        Invoke-ExternalGate "Frontend TypeScript no-emit check" { & npx.cmd tsc --noEmit }
    }
    finally { Pop-Location }

    if (Test-Path -LiteralPath (Join-Path $Root ".git")) {
        Invoke-ExternalGate "Git whitespace check (pager disabled)" {
            $env:GIT_PAGER = "cat"
            $env:PAGER = "cat"
            & git -C $Root --no-pager diff --check
        }
    }

    Invoke-ExternalGate "Post-change migration application check" {
        & $Python (Join-Path $Root "backend\manage.py") migrate --check
    }
    Invoke-ExternalGate "Post-change migration drift check" {
        & $Python (Join-Path $Root "backend\manage.py") makemigrations --check --dry-run
    }

    Remove-PatchBackups

    Write-Host ""
    Write-Host "UDEMY_TOPIC_NEW_ONLY_PATCH=PASS"
    Write-Host "UDEMY_TOPIC_NEW_ONLY=PASS"
    Write-Host "Manual custom-admin runs now use public /topic/<topic>/free/ sources when a topic is selected."
    Write-Host "All-topics runs continue to use /courses/free/."
    Write-Host "Manual runs skip courses already stored before the requested new-course limit is counted."
    Write-Host "English is verified from public course detail metadata instead of the blocked lang query facet."
    Write-Host "Certification Prep remains intentionally disabled until LearnLoot can prove free pricing without using blocked facets."
    Write-Host "No database migration was required."
}
catch {
    $message = $_.Exception.Message
    Write-Host ""
    if ($WriteStarted) {
        Write-Host ("UDEMY_TOPIC_NEW_ONLY_PATCH=FAIL: " + $message)
        Restore-Source
    }
    else {
        Write-Host ("UDEMY_TOPIC_NEW_ONLY_PATCH=FAIL_PREFLIGHT: " + $message)
    }
    exit 1
}
